DROP TABLE IF EXISTS `continents`;
CREATE TABLE `continents` (
  `code` VARCHAR(2)  NOT NULL DEFAULT '',
  `name` VARCHAR(15) NOT NULL DEFAULT '',
  UNIQUE KEY `code` (`code`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;


DROP TABLE IF EXISTS `languages`;
CREATE TABLE `languages` (
  `code` VARCHAR(2)  NOT NULL DEFAULT '',
  `name` VARCHAR(50) NOT NULL DEFAULT '',
  `native` VARCHAR(50) NOT NULL DEFAULT '',
  `rtl` TINYINT(1) NOT NULL DEFAULT 0,
  UNIQUE KEY `code` (`code`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;


DROP TABLE IF EXISTS `currencies`;
CREATE TABLE `currencies` (
  `code` VARCHAR(3)  NOT NULL DEFAULT '',
  `name` VARCHAR(35) NOT NULL DEFAULT '',
  `native` VARCHAR(40) NOT NULL DEFAULT '',
  `symbol` VARCHAR(5) NOT NULL DEFAULT '',
  `symbolNative` VARCHAR(5) NOT NULL DEFAULT '',
  `numeric` CHAR(3) NOT NULL DEFAULT '',
  `decimals` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  `withdrawn` TINYINT(1) NOT NULL DEFAULT 0,
  UNIQUE KEY `code` (`code`),
  KEY `numeric` (`numeric`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;


DROP TABLE IF EXISTS `countries`;
CREATE TABLE `countries` (
  `code` VARCHAR(2)  NOT NULL DEFAULT '',
  `name` VARCHAR(50) NOT NULL DEFAULT '',
  `native` VARCHAR(50) NOT NULL DEFAULT '',
  `phone` VARCHAR(15) NOT NULL DEFAULT '',
  `continent` VARCHAR(2) NOT NULL DEFAULT '',
  `capital` VARCHAR(50) NOT NULL DEFAULT '',
  `currency` VARCHAR(35) NOT NULL DEFAULT '',
  `languages` VARCHAR(29) NOT NULL DEFAULT '',
  UNIQUE KEY `code` (`code`),
  KEY `continent` (`continent`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

